create extension if not exists pgcrypto;
create table if not exists public.colleges(id uuid primary key default gen_random_uuid(),canonical_name text not null,edmingle_organization_id text unique,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.user_college_access(user_id uuid not null references auth.users(id) on delete cascade,college_id uuid not null references public.colleges(id) on delete cascade,role text not null check(role in('super_admin','college_admin','department_admin','teacher','viewer')),active boolean not null default true,primary key(user_id,college_id));
create table if not exists public.edmingle_students(id uuid primary key default gen_random_uuid(),college_id uuid not null references public.colleges(id) on delete cascade,edmingle_user_id text not null,registration_number text,name text not null,email text,mobile text,department text,batch_id text,average_completion numeric,synced_at timestamptz not null default now(),unique(college_id,edmingle_user_id));
create table if not exists public.edmingle_content_progress(id bigint generated always as identity primary key,college_id uuid not null references public.colleges(id) on delete cascade,edmingle_user_id text not null,class_id text not null,resource_id text not null,resource_name text not null,resource_type text,status text not null check(status in('completed','not_completed','not_attempted','unknown')),viewed_at timestamptz,synced_at timestamptz not null default now(),unique(college_id,edmingle_user_id,class_id,resource_id));
create table if not exists public.edmingle_test_results(id bigint generated always as identity primary key,college_id uuid not null references public.colleges(id) on delete cascade,edmingle_user_id text not null,assessment_id text not null,assessment_name text not null,batch_id text,marks_obtained numeric,total_marks numeric,percentage numeric,position integer,evaluated boolean,submitted_at timestamptz,synced_at timestamptz not null default now(),unique(college_id,edmingle_user_id,assessment_id));
create or replace function public.can_access_college(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_college_access a where a.user_id=auth.uid() and a.college_id=target and a.active);$$;
revoke all on function public.can_access_college(uuid) from public;grant execute on function public.can_access_college(uuid) to authenticated;
alter table public.colleges enable row level security;alter table public.user_college_access enable row level security;alter table public.edmingle_students enable row level security;alter table public.edmingle_content_progress enable row level security;alter table public.edmingle_test_results enable row level security;
create policy "college read" on public.colleges for select to authenticated using(public.can_access_college(id));
create policy "own mapping read" on public.user_college_access for select to authenticated using(user_id=auth.uid());
create policy "student college read" on public.edmingle_students for select to authenticated using(public.can_access_college(college_id));
create policy "progress college read" on public.edmingle_content_progress for select to authenticated using(public.can_access_college(college_id));
create policy "test college read" on public.edmingle_test_results for select to authenticated using(public.can_access_college(college_id));
create index if not exists edmingle_students_college_idx on public.edmingle_students(college_id);create index if not exists edmingle_progress_student_idx on public.edmingle_content_progress(college_id,edmingle_user_id);create index if not exists edmingle_tests_assessment_idx on public.edmingle_test_results(college_id,assessment_id,percentage desc);
